    circumference = PinEdgeRadius * 2*3.1415929/1000 # Unit: StandardMKS
    import time
    import clr
    import re
    clr.AddReference("System.Windows.Forms ")
    startTime = time.time()
    def CreateBonded_in_contact(pinBallRadius):
        with Transaction(True):
            systemDefaultBondedName = "Connect Topology"
            '''
            Purpose: Create a group to put all bonded together and name group as "Script_Bonded_Group"
            '''
            groupName = "_Bonded_by_script"
            contactRegion_grp_ansys = Ansys.ACT.Automation.Mechanical.Connections.ConnectionGroup
            connectionGroup=ExtAPI.DataModel.Project.Model.Connections.GetChildren[contactRegion_grp_ansys](True)
            connection_Group = [i.Name for i in connectionGroup]
            if groupName not in connection_Group:
                connections_bonded_grp = Model.Connections.AddConnectionGroup()
                connections_bonded_grp.Name = groupName
            else:
                tempList = [i.Name for i in Model.Connections.Children]
                connections_bonded_grp = Model.Connections.Children[tempList.index(groupName)]
                # print (connections_bonded_grp.Name) # test only
            '''
            purpose: Record all Conect Topology in "_Bonded_by_script" to prevent duplicated item.
            '''
            bondedList = [i.Name for i in connections_bonded_grp.Children]
            '''
            Purpose: Create bonded from name selection
            '''
            ContactRegion_grp_ansys = Ansys.ACT.Automation.Mechanical.Connections.ContactRegion
            Bonded_grp_existing=ExtAPI.DataModel.Project.Model.Connections.GetChildren[ContactRegion_grp_ansys](True)
            for i in ExtAPI.DataModel.Project.Model.NamedSelections.GetChildren[Ansys.ACT.Automation.Mechanical.NamedSelection](True):
                # ("="*60)
                #print (type(i.Name[0:len(systemDefaultBondedName)]))
                #print ("="*60)
            	if i.Name[0:len(systemDefaultBondedName)] == systemDefaultBondedName:
            	    '''
            	    Pick the Name selection id in Mechamical.
            	    It is used to recognize the face id in Mechanical.
            	    And only pick the name selection which made of 2 faces.
            	    '''
            	    pair_check = i.Location.Ids
            	    if len(pair_check) == 2:
            	        face1 = ExtAPI.SelectionManager.CreateSelectionInfo(SelectionTypeEnum.GeometryEntities)
            	        face1.Ids = [pair_check[0]]
            	        face2 = ExtAPI.SelectionManager.CreateSelectionInfo(SelectionTypeEnum.GeometryEntities)
            	        face2.Ids = [pair_check[1]]
            	        if i.Name not in bondedList:
            	            nameSelection = i
            	            bonded = connections_bonded_grp.AddContactRegion()
            	            bonded.SourceLocation = face1
            	            bonded.TargetLocation = face2
            	            bonded.Name = i.Name
            	            # bonded.ShellThicknessEffect = True
            	            bonded.ShellThicknessEffect = False
            '''
            Set the pinball for each bonded type
            '''
            contacts = DataModel.GetObjectsByType(DataModelObjectCategory.ContactRegion)
            changeCount = 0
            for cont in contacts:
                if (cont.ContactType == ContactType.Bonded):
                    cont.PinballRegion = ContactPinballType.Radius
                    cont.PinballRadius = Quantity(str(pinBallRadius*2)+"[mm]")
                    offsetN = pinBallRadius*2
                    cont.BondedMaximumOffset = Quantity(offsetN, "mm")
                    changeCount = changeCount +1
        text = "Done, total " + str(changeCount) +  " bonded are set with pinball " + str(pinBallRadius)+" mm."
        print (text)
    def edgeCircelMesh(meshEdge):
        with Transaction(True):
            if meshEdge:
                for obj in objs:
                    match = re.search(findText, obj.Name)
                    if match:
                        pair_check = obj.Location.Ids
                        if len(pair_check) == 2:
                            for face in pair_check:
                                tempSel = ExtAPI.SelectionManager.CreateSelectionInfo(SelectionTypeEnum.GeometryEntities)
                                tempSel.Ids = [face]
                                faceMesh = ExtAPI.DataModel.GeoData.GeoEntityById(tempSel.Ids[0])
                                if str(faceMesh.Bodies[0].BodyType) == "GeoBodySheet":
                                    if faceMesh.Edges[0].CurveType == GeoCurveTypeEnum.GeoCurveCircle:
                                        GeoUnit = str(ExtAPI.DataModel.Project.Model.Geometry.LengthUnit)
                                        if GeoUnit == "StandardMKS":
                                            for edge in faceMesh.Edges:
                                                if edge.Length <= circumference:
                                                    print(edge.Id)
                                                    myMesh = Model.Mesh
                                                    scr_Mesh_Bonded_faceMesh = myMesh.AddSizing()
                                                    selection = ExtAPI.SelectionManager.CreateSelectionInfo(SelectionTypeEnum.GeometryEntities)
                                                    selection.Ids = [edge.Id]
                                                    scr_Mesh_Bonded_faceMesh.Location = selection
                                                    scr_Mesh_Bonded_faceMesh.ElementSize = Quantity(circleEdgeSize, "mm")
    CreateBonded_in_contact(pinBallRadius)
    edgeCircelMesh(meshEdge)
    ExtAPI.DataModel.Tree.Refresh()
