    deltaT = round(deltaT, 1)
    try:
        act_elapsed_sec = _act_time.time() - _ACT_START_TIME
        log_usage("Mech_bonded", "20231030", act_elapsed_sec, 2400)
    except:
        pass

    print("[UI_OUTPUT] " + str("Done, took {} seconds".format(deltaT)))

